import fs from 'node:fs/promises'
import path from 'node:path'
import { config } from '../config.js'
import { HttpError } from '../utils/http.js'

/**
 * Small storage abstraction so the JSON-backed demo can swap to Supabase
 * Storage (or another object store) without touching the assignment routes.
 *
 * Keys are generated by the server and are always flat. That avoids path
 * traversal and keeps Supabase object paths predictable.
 */
function safeKey(key) {
  if (!key || typeof key !== 'string' || key.includes('/') || key.includes('\\')) {
    throw new HttpError(400, 'Invalid storage key.')
  }
  return key
}

function getBucket(bucket) {
  if (bucket === 'teacher') return config.supabaseBucketTeacherDocs
  if (bucket === 'teacher-docs') return config.supabaseBucketTeacherDocs
  if (bucket === 'assignments') return config.supabaseBucketAssignments
  return config.supabaseBucket
}

function supabaseEndpoint(bucket, key) {
  const base = config.supabaseUrl.replace(/\/+$/, '')
  const b = encodeURIComponent(getBucket(bucket))
  return `${base}/storage/v1/object/${b}/${encodeURIComponent(safeKey(key))}`
}

function signedUrlEndpoint(bucket, key) {
  const base = config.supabaseUrl.replace(/\/+$/, '')
  const b = encodeURIComponent(getBucket(bucket))
  return `${base}/storage/v1/object/sign/${b}/${encodeURIComponent(safeKey(key))}`
}

function requireSupabase() {
  if (!config.supabaseUrl || !config.supabaseServiceRoleKey) {
    throw new HttpError(
      503,
      'Supabase Storage is selected but SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY is missing.',
    )
  }
}

async function supabaseError(response, fallback) {
  let detail = ''
  try {
    const payload = await response.json()
    detail = payload?.message || payload?.error || ''
  } catch {
    detail = await response.text().catch(() => '')
  }
  throw new HttpError(502, detail ? `Supabase Storage: ${detail}` : fallback)
}

export const storage = {
  driver: config.storageDriver,

  async put({ key, buffer, contentType = 'application/octet-stream', bucket = 'default' }) {
    const objectKey = safeKey(key)
    if (!buffer?.length) throw new HttpError(400, 'The uploaded file is empty.')

    if (config.storageDriver === 'supabase') {
      requireSupabase()
      const response = await fetch(supabaseEndpoint(bucket, objectKey), {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${config.supabaseServiceRoleKey}`,
          apikey: config.supabaseServiceRoleKey,
          'Content-Type': contentType,
          'x-upsert': 'true',
        },
        body: buffer,
      })
      if (!response.ok) await supabaseError(response, 'Upload failed.')
      return { key: objectKey, driver: 'supabase', bucket: getBucket(bucket) }
    }

    if (config.storageDriver !== 'local') {
      throw new HttpError(503, `Unknown storage driver: ${config.storageDriver}`)
    }

    await fs.mkdir(config.uploadDir, { recursive: true })
    await fs.writeFile(path.join(config.uploadDir, objectKey), buffer)
    return { key: objectKey, driver: 'local', bucket: null }
  },

  async get(key, bucket = 'default') {
    const objectKey = safeKey(key)

    if (config.storageDriver === 'supabase') {
      requireSupabase()
      const response = await fetch(supabaseEndpoint(bucket, objectKey), {
        headers: {
          Authorization: `Bearer ${config.supabaseServiceRoleKey}`,
          apikey: config.supabaseServiceRoleKey,
        },
      })
      if (response.status === 404) throw new HttpError(404, 'The submitted file is no longer available.')
      if (!response.ok) await supabaseError(response, 'Could not read the submitted file.')
      return {
        buffer: Buffer.from(await response.arrayBuffer()),
        contentType: response.headers.get('content-type') || 'application/octet-stream',
      }
    }

    try {
      const buffer = await fs.readFile(path.join(config.uploadDir, objectKey))
      return { buffer, contentType: 'application/octet-stream' }
    } catch {
      throw new HttpError(404, 'The submitted file is no longer available.')
    }
  },

  async getSignedUrl(key, bucket = 'teacher', expiresIn = 300) {
    if (config.storageDriver !== 'supabase') return null
    requireSupabase()
    const objectKey = safeKey(key)
    const response = await fetch(signedUrlEndpoint(bucket, objectKey), {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${config.supabaseServiceRoleKey}`,
        apikey: config.supabaseServiceRoleKey,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ expiresIn }),
    })
    if (!response.ok) await supabaseError(response, 'Could not generate signed URL.')
    const data = await response.json().catch(() => ({}))
    const signedUrl = data.signedURL || data.signed_url || data.url || null
    if (!signedUrl) return null
    if (signedUrl.startsWith('http')) return signedUrl
    const base = config.supabaseUrl.replace(/\/+$/, '')
    // The Storage API returns a path such as `/object/sign/...`. The public
    // gateway lives under `/storage/v1`, which is easy to forget.
    if (signedUrl.startsWith('/object/')) return `${base}/storage/v1${signedUrl}`
    return `${base}${signedUrl}`
  },

  async remove(key, bucket = 'default') {
    if (!key) return
    const objectKey = safeKey(key)
    if (config.storageDriver === 'supabase') {
      if (!config.supabaseUrl || !config.supabaseServiceRoleKey) return
      await fetch(supabaseEndpoint(bucket, objectKey), {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${config.supabaseServiceRoleKey}`,
          apikey: config.supabaseServiceRoleKey,
        },
      }).catch(() => {})
      return
    }
    await fs.unlink(path.join(config.uploadDir, objectKey)).catch(() => {})
  },
}

export function storageMeta() {
  return {
    driver: config.storageDriver,
    configured:
      config.storageDriver === 'local' ||
      Boolean(config.supabaseUrl && config.supabaseServiceRoleKey),
    bucket: config.storageDriver === 'supabase' ? config.supabaseBucket : null,
    buckets: {
      assignments: config.storageDriver === 'supabase' ? config.supabaseBucketAssignments : null,
      teacherDocs: config.storageDriver === 'supabase' ? config.supabaseBucketTeacherDocs : null,
    },
  }
}
